import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def f(g):
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*len(g[0]) for _ in g]; out=[r[:] for r in g]
    for i in range(len(g)):
        for j in range(len(g[0])):
            v=g[i][j]
            if v==bg or seen[i][j]: continue
            # extent of this color
            ii=[k for k in range(len(g)) for l in range(len(g[0])) if g[k][l]==v]
            rs=[x for x,_ in ii]; cs=[y for _,y in ii]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            if r0<0 or r1>=len(g) or c0<0 or c1>=len(g[0]): continue
            for x in range(r0+1,r1):
                for y in range(c0+1,c1):
                    if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==v:
                        out[x][y]=8
    return out
